#!/usr/bin/env python3
"""Enforce the Open Horizons fleet task contract at Copilot hook boundaries.

Phase 0 `CONFINED_LITE`. Command tools are removed from fleet subagents rather
than inspected, the control plane lives outside the repository and is sealed
with a launcher key, and every verdict input is content-addressed. The
regular-expression tripwire is retained for evidence only; it is not a
security boundary.
"""

from __future__ import annotations

# Importing a sibling module must not leave `__pycache__` inside the hook
# surface; the repository treats generated bytecode there as residue.
import sys

sys.dont_write_bytecode = True

import json  # noqa: E402
import os  # noqa: E402
import re  # noqa: E402
import subprocess  # noqa: E402
import time  # noqa: E402
import uuid  # noqa: E402
from contextlib import contextmanager  # noqa: E402
from datetime import UTC, datetime  # noqa: E402
from pathlib import Path  # noqa: E402
from typing import Any, Iterator  # noqa: E402

sys.path.insert(0, str(Path(__file__).resolve().parent))

import fleet_policy  # noqa: E402
import fleet_sandbox  # noqa: E402
from fleet_policy import PolicyError, SealError  # noqa: E402


# The deadline for bounded work starts when the process starts, not when the
# validation function is entered, so pre-validation git work is inside it.
PROCESS_START = time.monotonic()

CONTRACT_ENV = fleet_policy.CONTRACT_ENV
COPILOT_RUNAWAY_BLOCK_GUARD = fleet_policy.COPILOT_RUNAWAY_BLOCK_GUARD
VALIDATION_GATE_DESCRIPTOR = Path(".github") / "hooks" / "30-validation-gate.json"

WORKER_RESULT = re.compile(
    r"^FLEET_RESULT:\s*(T\d{3}-\d{3}):\s*(PASS|FAIL|BLOCKED)\s*$",
    re.MULTILINE,
)
VALIDATOR_RESULT = re.compile(
    r"^FLEET_VALIDATION:\s*(T\d{3}-\d{3}):\s*(PASS|FAIL)\s*$",
    re.MULTILINE,
)
COMMAND_KEYS = {"cmd", "command", "script"}
